import sys
import re

def main():
    text = sys.stdin.read()
    env = {}
    assign_re = re.compile(r'^\s*([A-Za-z_]\w*)\s*<-\s*(.+?)\s*;?\s*$')
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('//'):
            continue
        # strip trailing inline comments
        if '//' in line:
            line = line.split('//', 1)[0].strip()
            if not line:
                continue
        m = assign_re.match(line)
        if not m:
            continue
        target, expr = m.group(1), m.group(2).strip().rstrip(';').strip()
        if re.fullmatch(r'-?\d+', expr):
            val = int(expr)
        elif re.fullmatch(r'-?\d+\.\d*', expr):
            val = float(expr)
        elif re.fullmatch(r'[A-Za-z_]\w*', expr):
            val = env.get(expr)
        else:
            # fallback: evaluate simple expression with current variables
            try:
                val = eval(expr, {"__builtins__": {}}, dict(env))
            except Exception:
                val = expr
        env[target] = val
    parts = []
    for name in ['a', 'b', 'c', 'd', 'TMP']:
        parts.append(f"{name} ?= {env.get(name)};")
    print(' '.join(parts))

if __name__ == '__main__':
    main()
